import java.util.*;
import java.math.BigInteger;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < N; i++) {
            sb.append(sc.nextInt());
        }
        String s = sb.toString();
        BigInteger ONE = BigInteger.ONE;

        for (int len = 1; len <= N; len++) {
            String pref = s.substring(0, len);
            if (pref.charAt(0) == '0') continue;

            BigInteger cur = new BigInteger(pref);
            int pos = 0;
            boolean ok = true;

            while (pos < N) {
                String cs = cur.toString();
                int clen = cs.length();

                if (pos + clen > N) {
                    ok = false;
                    break;
                }

                if (!s.regionMatches(pos, cs, 0, clen)) {
                    ok = false;
                    break;
                }

                pos += clen;
                cur = cur.add(ONE);
            }

            if (ok && pos == N) {
                System.out.println(pref);
                return;
            }
        }
    }
}
